function welcome(){leaveView();state.server=true;state.page='welcome';state.channel='welcome';state.peer=null;side();$('#title').textContent='Welcome to Nova';const v=$('#view');v.replaceChildren();const hero=el('section','welcome-hero');hero.append(media('Nova12.png','','welcome-logo'),el('span','eyebrow','YOU BELONG HERE'),el('h1','','Hey '+person(state.me.uid).name+'.\nWelcome to Nova.'),el('p','','A place to play, share discoveries, and find your people.'),button('Say hello in general',()=>openChannel('general'),'primary'));v.append(hero);const cards=el('div','welcome-actions');for(const [glyph,title,desc,action]of [['friends','Find your people','Meet friends and start a conversation.',()=>navigate('friends')],['nitro','Make it yours','Discover the next Nova collection.',()=>navigate('nitro')],['suggestions','Build Nova with us','Send your ideas directly to the owner.',()=>feedback('suggestions')]]){const b=button('',action);b.append(icon(glyph),el('h3','',title),el('p','muted',desc));cards.append(b)}v.append(cards);const recent=el('section','new-members');recent.append(el('h2','','New around here'),el('p','muted','A warm welcome to the latest members of Nova.'));Object.entries(state.profiles).sort((a,b)=>(b[1].joined||0)-(a[1].joined||0)).slice(0,8).forEach(([id])=>{const b=button('',()=>profile(id),'new-member');b.append(avatar(id),el('span','',person(id).name));recent.append(b)});v.append(recent);motion()}
function feedback(kind){leaveView();state.server=true;state.page='feedback';state.channel=kind;side();$('#title').textContent=kind==='report'?'Report an issue':'Suggestions';const view=$('#view');view.replaceChildren();const wrap=el('section','feedback-wrap'),intro=el('div','feedback-intro');intro.append(icon(kind),el('span','eyebrow','PRIVATE STAFF SUPPORT'),el('h1','',kind==='report'?'Let’s make it right.':'Your next great idea starts here.'),el('p','muted',kind==='report'?'Tell us what happened. Your report is private and visible only to you and Nova staff.':'Help shape Nova. Send a private suggestion to Nova staff.'));wrap.append(intro);const form=el('form','feedback-form'),subject=el('input'),text=el('textarea');subject.required=true;subject.maxLength=100;text.required=true;text.minLength=10;text.maxLength=4000;text.rows=7;subject.placeholder=kind==='report'?'What went wrong?':'Give your idea a title';text.placeholder=kind==='report'?'Include the username, channel, or steps that help explain the issue.':'What would you like to see, and how would it help?';for(const [title,input]of [['Subject',subject],['Details',text]]){const label=el('label','field',title);label.append(input);form.append(label)}const submit=el('button','primary','Send to staff');form.append(submit);const result=el('p','feedback-result');result.setAttribute('role','status');form.append(result);form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;submit.disabled=true;try{await api.send('feedback/'+state.me.uid,{author:state.me.uid,text:text.value.trim(),subject:subject.value.trim(),kind});form.reset();result.textContent='Sent. Thank you for helping make Nova better.'}catch(err){fail(err)}finally{submit.disabled=false}};wrap.append(form);wrap.append(button('Your submissions & replies',()=>supportInbox(false,kind)));if(moderator())wrap.append(button('Open staff inbox',()=>staffFeedback(kind)));view.append(wrap);motion()}
function ownerInbox(){const d=modal('Owner inbox');d.classList.add('inbox-modal');const list=el('div','owner-inbox');d.append(list);const stop=api.watch('feedback',all=>{list.replaceChildren();const items=Object.values(all).flatMap(v=>Object.values(v)).sort((a,b)=>b.createdAt-a.createdAt);for(const item of items){const card=el('article','inbox-item');card.append(el('span','eyebrow',item.kind==='report'?'REPORT':'SUGGESTION'),el('h3','',item.subject),el('small','muted',person(item.author).name+' · '+new Date(item.createdAt).toLocaleString()),el('p','',item.text));list.append(card)}if(!items.length)list.append(el('p','muted','All caught up. Reports and suggestions will arrive here.'))},fail);d.addEventListener('close',stop,{once:true})}
function serverSettings(){if(role(state.me.uid)!=='owner')return;const d=modal('Server settings');d.classList.add('server-settings-modal');const body=el('div','server-settings-host');d.append(body);serverManager(body,profileContext());}

function leaveView(){$('#view').classList.remove('nova-store-view','nova-nitro-view');const stop=stopMessages;stopMessages=()=>{};messagePath='';stop();$('#view').getAnimations().forEach(a=>a.cancel());document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function openAssistance(){leaveView();state.server=true;state.page='ai';state.channel='ai-assistance';state.peer=null;side();$('#title').textContent='Nova AI assistance';const frame=el('iframe','chat-ai-frame');frame.src='ai.html';frame.title='Nova AI';$('#view').replaceChildren(frame);motion()}
addEventListener('message',e=>{const f=$('.chat-ai-frame');if(f&&e.origin===location.origin&&e.source===f.contentWindow&&['closeAI','closeApp'].includes(e.data?.novaAction))openChannel('general')});
function staffFeedback(kind){if(!moderator())return;window.novaMarkRead?.(kind==='report'?'reports':'suggestions');leaveView();state.server=true;state.page='staff-feedback';state.channel=kind==='report'?'staff-reports':'staff-suggestions';state.peer=null;side();$('#title').textContent=kind==='report'?'Staff · Reports':'Staff · Suggestions';const host=el('section','support-page');$('#view').replaceChildren(host);const tabs=el('div','tabs');tabs.append(button('Reports',()=>staffFeedback('report'),kind==='report'?'selected':''),button('Suggestions',()=>staffFeedback('suggestions'),kind==='suggestions'?'selected':''));host.append(tabs);const list=el('div','support-list');host.append(list);stopMessages=watchTickets(list,true,kind);motion()}
function supportInbox(staff,kind){const d=modal('Your submissions & replies');const list=el('div','support-list');d.append(list);const stop=watchTickets(list,staff,kind);d.addEventListener('close',stop,{once:true})}
function watchTickets(host,staff,kind){let replyStops=[];const path=staff?'feedback':'feedback/'+state.me.uid;const stop=api.watch(path,all=>{replyStops.forEach(s=>s());replyStops=[];host.replaceChildren();const roots=staff?all:{[state.me.uid]:all};const tickets=Object.entries(roots).flatMap(([uid,v])=>Object.entries(v).map(([id,t])=>({uid,id,...t}))).filter(t=>t.kind===kind).sort((a,b)=>b.createdAt-a.createdAt);for(const t of tickets){const card=el('article','inbox-item');const identity=button('',()=>profile(t.uid),'ticket-identity');identity.append(avatar(t.uid),label(t.uid));card.append(identity);card.append(el('span','eyebrow',t.kind==='report'?'REPORT':'SUGGESTION'),el('h3','',t.subject),el('small','muted',person(t.uid).name+' · '+new Date(t.createdAt).toLocaleString()),el('p','',t.text));const replies=el('div','ticket-replies');card.append(replies);replyStops.push(api.watch('feedbackReplies/'+t.uid+'/'+t.id,items=>{replies.replaceChildren();Object.values(items).sort((a,b)=>a.createdAt-b.createdAt).forEach(r=>{const item=el('div','staff-reply');item.append(el('b','',person(r.author).name+' · Staff'),el('p','',r.text));replies.append(item)})},fail));if(staff){const form=el('form','ticket-reply-form'),input=el('textarea'),send=el('button','primary','Send reply');input.required=true;input.maxLength=4000;input.placeholder='Reply to '+person(t.uid).name;input.setAttribute('aria-label','Staff reply');form.append(input,send);form.onsubmit=async e=>{e.preventDefault();if(!input.value.trim())return;send.disabled=true;try{await control('staffReply',{uid:t.uid,id:t.id,text:input.value.trim()});input.value='';toast('Reply sent.')}catch(err){fail(err)}finally{send.disabled=false}};card.append(form,button('Delete submission',task(async()=>{if(window.confirm('Delete this submission?'))await control('deleteFeedback',{uid:t.uid,id:t.id})}),'ticket-delete'))}host.append(card)}if(!tickets.length)host.append(el('p','muted','No submissions here yet.'))},fail);return ()=>{stop();replyStops.forEach(s=>s())}}

const appealButton=button('Request an unban',()=>{const d=modal('Ban appeal');const host=el('div');d.append(host);appealUI(host,'chat')});document.querySelector('#loading').append(appealButton);

function notificationDM(uid){if(uid==='nova-bot'&&state.me){sessionStorage.removeItem('nova-notification-dm');openBot();return}if(state.me&&state.friends[uid]){sessionStorage.removeItem('nova-notification-dm');openDM(uid)}}
addEventListener('nova-open-dm',e=>notificationDM(e.detail));
addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.novaAction==='notificationDM')notificationDM(e.data.uid)});

function openBot(){window.novaMarkRead?.('bot');leaveView();state.server=false;state.page='bot';state.peer='nova-bot';side();$('#title').textContent='Nova Bot · Online';const log=el('section','nova-bot-log');$('#view').replaceChildren(log);stopMessages=api.watch('botMessages/'+state.me.uid,v=>{log.replaceChildren();for(const m of Object.values(v).sort((a,b)=>a.createdAt-b.createdAt)){const card=el('article','nova-bot-card'),identity=el('div','ticket-identity');identity.append(avatar('nova-bot'),el('strong','','Nova Bot'),el('span','role','APP'));card.append(identity,el('small','muted',new Date(m.createdAt).toLocaleString()),el('h3','',m.subject||'Staff response'),el('small','muted',m.kind==='music-party-invite'?'Music invitation · '+(m.staffName||'Nova friend'):m.kind==='nitro-gift'?'Nitro gift from '+m.staffName:(m.staffRole==='owner'?'Owner':'Staff')+' response · '+m.staffName));const body=el('div','message-text');formatMessage(body,m.text);card.append(body);if(m.kind==='music-party-invite'&&m.inviteId){const approve=el('button','primary','Accept and join party');approve.onclick=async()=>{if(preview){approve.textContent='Preview invitation';return;}approve.disabled=true;try{const {auth}=await import('./account-firebase.js');const r=await fetch('/api/music',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await auth.currentUser.getIdToken()},body:JSON.stringify({action:'acceptPartyInvite',id:m.inviteId})});const result=await r.json();if(!r.ok)throw Error(result.error||'Could not join party.');localStorage.setItem('nova-music-party-'+state.me.uid,result.code);approve.textContent='Joined party';const host=window.parent;host.dispatchEvent(new Event('nova-music-party-joined'));if(host.NovaOS)host.NovaOS.open('music');else host.NovaMusic?.open();}catch(e){approve.disabled=false;approve.textContent=e.message;}};card.append(approve);}log.append(card)}if(!log.children.length)log.append(el('p','muted','Staff replies to your reports and suggestions will arrive here.'))},fail)}

addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||parent===window)return;if(e.data?.novaAction==='osSupportInbox'&&['report','suggestions'].includes(e.data.kind)&&state.me)supportInbox(false,e.data.kind)});

addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&parent!==window&&e.data?.novaAction==='osChatTab'&&e.data.tab==='nitro'&&state.me)navigate('nitro')});

addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&parent!==window&&e.data?.novaAction==='osOpenShop'&&state.me){sessionStorage.removeItem('nova-os-chat-tab');navigate('shop')}});

addEventListener('nova-chat-profile-updated',()=>{if(state.me)refresh()});
